{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "금연구역 지정 장소를 빌려 점유한 자가 그 구역 안에 흡연구역을 설치·운영할 수 있는 주체에 포함되는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "금연구역으로 지정된 해당 장소의 점유자는 그 구역 내에 흡연구역을 설치·운영할 수 있습니다. 조례 제8조제1항은 제5조제1항에 따라 금연구역으로 지정되는 해당 장소의 소유자·점유자 또는 관리자에게 흡연구역 설치·운영을 할 수 있도록 정하고 있으므로, 소유자는 아니지만 그 장소를 빌려 점유하고 있는 자도 설치·운영 주체에 포함됩니다.",
          "b_ids": "금연:제8조제1항, 금연:제5조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
